import{_ as e,c as l,o as i,ag as t}from"./chunks/framework.C86mscM5.js";const u=JSON.parse('{"title":"日志、指标、链路与告警","description":"","frontmatter":{},"headers":[],"relativePath":"devops/observability/signals-and-alerting.md","filePath":"devops/observability/signals-and-alerting.md","lastUpdated":1788092044000}'),r={name:"devops/observability/signals-and-alerting.md"};function o(n,a,s,d,h,c){return i(),l("div",null,a[0]||(a[0]=[t('<h1 id="日志、指标、链路与告警" tabindex="-1">日志、指标、链路与告警 <a class="header-anchor" href="#日志、指标、链路与告警" aria-label="Permalink to &quot;日志、指标、链路与告警&quot;">​</a></h1><h2 id="统一上下文" tabindex="-1">统一上下文 <a class="header-anchor" href="#统一上下文" aria-label="Permalink to &quot;统一上下文&quot;">​</a></h2><p>服务应传播 Trace ID，并在结构化日志中记录 Trace ID、服务、环境、版本和请求结果。禁止记录密码、Token、完整身份证件或支付信息。</p><p>OpenTelemetry 提供统一的 API、SDK、语义约定和 Collector，可把遥测数据发送到不同后端。它解决采集与传输标准化，不替代存储、查询和告警平台。</p><h2 id="观测重点" tabindex="-1">观测重点 <a class="header-anchor" href="#观测重点" aria-label="Permalink to &quot;观测重点&quot;">​</a></h2><ul><li>面向用户：成功率、延迟、关键业务结果和前端体验。</li><li>面向服务：请求量、错误、延迟、饱和度及依赖调用。</li><li>面向资源：CPU、内存、磁盘、网络、队列和连接池。</li><li>面向变更：部署版本、配置修改、功能开关和扩缩容事件。</li></ul><h2 id="告警原则" tabindex="-1">告警原则 <a class="header-anchor" href="#告警原则" aria-label="Permalink to &quot;告警原则&quot;">​</a></h2><ul><li>告警应对应需要人立即采取的动作，并链接 Dashboard 和 Runbook。</li><li>优先根据 SLO 消耗或用户影响告警，资源阈值用于诊断和容量预警。</li><li>设置持续时间、抑制、分组和维护窗口，减少瞬时抖动与告警风暴。</li><li>记录负责人、严重等级和升级路径；定期删除无动作或长期静默的告警。</li></ul><h2 id="数据治理" tabindex="-1">数据治理 <a class="header-anchor" href="#数据治理" aria-label="Permalink to &quot;数据治理&quot;">​</a></h2><p>根据排障、合规和成本设置采样与保留期。高基数 Label 会显著增加指标成本；Debug 日志不应在生产无限保留。遥测管道自身也需要队列、丢弃量和延迟监控。</p>',10)]))}const _=e(r,[["render",o]]);export{u as __pageData,_ as default};
